def progress_from_issues(apps, schema_editor):
    JointProject = apps.get_model('bizpartners', 'JointProject')
    JointIssue = apps.get_model('bizpartners', 'JointIssue')
    for project in JointProject.objects.all():
        qs = JointIssue.objects.filter(project=project)
        total = qs.count()
        if total:
            pct = round(qs.filter(is_done=True).count() * 100 / total)
            JointProject.objects.filter(pk=project.pk).update(progress=pct)


